mapper.update:
UPDATE camera_looks SET
    sort_order = #{sortOrder},
    version = version + 1,
    updated_by = #{updatedBy},
    updated_at = #{updatedAt}
WHERE id = #{id} AND kind = #{kind}

mapper.select:
SELECT 
FROM camera_looks
WHERE kind = #{kind} AND look_key = #{lookKey}

SELECT 
FROM camera_looks

    kind = #{kind}
    AND status = #{status}

        AND (look_key ILIKE CONCAT('%', #{q}, '%') OR names::text ILIKE CONCAT('%', #{q}, '%'))


ORDER BY kind ASC, sort_order ASC, id ASC
LIMIT #{limit}
